output_text:
[
  {
    "id": "must_take_entry_cart",
    "text": "A shopper must take the entry cart before doing the shopping or exiting.",
    "abstraction": {
      "state_properties": {
        "at_entry_cart_station": {
          "and": [
            "at(1,5)",
            "cartAt(1,5)"
          ]
        },
        "has_cart": "hasCart"
      },
      "events": {
        "take_entry_cart": {
          "pre": {
            "and": [
              "at_entry_cart_station",
              "PICKUP_CART"
            ]
          },
          "post": "has_cart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "take_entry_cart"
    }
  },
  {
    "id": "items_only_with_cart",
    "text": "A shopper is prohibited from picking up shelf items unless they currently have a cart.",
    "abstraction": {
      "state_properties": {
        "has_cart": "hasCart",
        "cartless": {
          "not": "hasCart"
        }
      },
      "events": {
        "item_pickup": {
          "pre": "PICKUP_ITEM",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "item_pickup",
          "cartless"
        ]
      }
    }
  },
  {
    "id": "no_hand_carrying",
    "text": "A shopper should not carry merchandise by hand inside the store.",
    "abstraction": {
      "state_properties": {
        "carrying_by_hand": "handFull",
        "using_cart_instead": {
          "and": [
            "hasCart",
            {
              "not": "handFull"
            }
          ]
        }
      },
      "events": {
        "hand_item_taken": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              {
                "not": "hasCart"
              }
            ]
          },
          "post": "handFull"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "carrying_by_hand"
    }
  },
  {
    "id": "return_cart_to_northwest_bay",
    "text": "After taking a cart, the shopper is obliged to return it to the northwest cart-return bay before exiting.",
    "abstraction": {
      "state_properties": {
        "northwest_cart_bay": "at(0,1)",
        "cart_parked_in_bay": "cartAt(0,1)",
        "has_cart": "hasCart"
      },
      "events": {
        "cart_taken": {
          "pre": "PICKUP_CART",
          "post": "has_cart"
        },
        "cart_returned_to_bay": {
          "pre": {
            "and": [
              "northwest_cart_bay",
              "has_cart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_in_bay"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "cart_taken",
      "discharge": "cart_returned_to_bay"
    }
  },
  {
    "id": "do_not_abandon_cart_elsewhere",
    "text": "A shopper is prohibited from leaving a cart anywhere except the northwest cart-return bay.",
    "abstraction": {
      "state_properties": {
        "northwest_cart_bay": "at(0,1)",
        "outside_cart_bay": {
          "not": "northwest_cart_bay"
        }
      },
      "events": {
        "leave_cart": {
          "pre": "LEAVE_CART",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "leave_cart",
          "outside_cart_bay"
        ]
      }
    }
  },
  {
    "id": "do_not_exit_with_cart",
    "text": "A shopper is prohibited from leaving the supermarket while still pushing or holding a cart.",
    "abstraction": {
      "state_properties": {
        "has_cart": "hasCart",
        "cartless": {
          "not": "hasCart"
        }
      },
      "events": {
        "exit_store": {
          "pre": "EXIT",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "exit_store",
          "has_cart"
        ]
      }
    }
  },
  {
    "id": "cart_return_lane_one_way",
    "text": "While pushing a cart on the west-side return lane, a shopper may not move east or south away from the cart-return bay.",
    "abstraction": {
      "state_properties": {
        "west_return_lane": {
          "or": [
            "at(0,1)",
            "at(0,2)",
            "at(0,3)",
            "at(0,4)"
          ]
        },
        "has_cart": "hasCart",
        "away_from_return_bay_move": {
          "or": [
            "E",
            "S"
          ]
        }
      },
      "events": {
        "pushing_cart_away_on_return_lane": {
          "pre": {
            "and": [
              "has_cart",
              "west_return_lane",
              "away_from_return_bay_move"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "pushing_cart_away_on_return_lane"
    }
  },
  {
    "id": "must_drop_cart_when_at_bay",
    "text": "When a shopper reaches the northwest cart-return bay with a cart, they must leave the cart there rather than continue moving with it.",
    "abstraction": {
      "state_properties": {
        "northwest_cart_bay": "at(0,1)",
        "has_cart": "hasCart",
        "cart_parked_in_bay": "cartAt(0,1)"
      },
      "events": {
        "arrive_at_bay_with_cart": {
          "pre": {
            "and": [
              "northwest_cart_bay",
              "has_cart"
            ]
          },
          "post": null
        },
        "leave_cart_in_bay": {
          "pre": {
            "and": [
              "northwest_cart_bay",
              "has_cart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_in_bay"
        },
        "move_with_cart_from_bay": {
          "pre": {
            "and": [
              "northwest_cart_bay",
              "has_cart",
              "MOVE"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "move_with_cart_from_bay"
    }
  }
]
